package main

import (
	"bufio"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"io/ioutil"
	"os"
	"path/filepath"

	"github.com/dgraph-io/badger/schema"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: go run main.go <source_file> <struct_name>")
		os.Exit(1)
	}

	sourceFile := os.Args[1]
	structName := os.Args[2]

	// Read the contents of the Go source file
	file, err := os.Open(sourceFile)
	if err != nil {
		fmt.Printf("Error opening file %s: %v\n", sourceFile, err)
		return
	}
	defer file.Close()

	// Parse the Go source code into an AST (Abstract Syntax Tree)
	fset := token.NewFileSet()
	tree, err := parser.ParseFile(fset, sourceFile, nil, 0)
	if err != nil {
		fmt.Printf("Parse error: %v\n", err)
		return
	}

	// Find all occurrences of the struct type
	var structs []schema.TypeDefinition
	for _, decl := range tree.Decls {
		switch t := decl.(*ast.GenDecl); t {
		case *ast.ImportStmt:
			continue
		default:
			if t.Tok == token.TYPE && t.Specs[0] == nil {
				if str, ok := t.Doc.(token.CommentGroup); ok {
					doc := str.Text
					for i, param := range t.Specs {
						if ast.IsExported(param.Name) {
							structType := fmt.Sprintf("%T", t.Type)
							if !strings.Contains(structType, "interface{") {
								structTypes := strings.Split(strings.ReplaceAll(structType, ".", ","), ",")
								structNames := strings.Split(doc, "\n")
								structName := strings.Split(structName, ".")[len(strings.Split(structName, "."))-1]
								for _, structTypeName := range structTypes {
									if strings.HasPrefix(structTypeName, structName+" ") {
										structDef := &schema.StructDefinition{
											Name:   structTypeName,
											Fields: make([]schema.FieldDefinition, len(structNames)),
										}
										for j := range structNames {
											structDef.Fields[j].Name = structNames[j]
											structDef.Fields[j].Type = schema.StringType
										}
										structs = append(structs, structDef)
									}
								}
							}
						}
					}
				}
			}
		}
	}

	// Write the generated Avro schemas to files
	for _, structDef := range structs {
		outputPath := filepath.Join(filepath.Dir(sourceFile), fmt.Sprintf("%s.avsc", structDef.Name))
		err := ioutil.WriteFile(outputPath, []byte(schema.ToAvroSchema(structDef)), 0644)
		if err != nil {
			fmt.Printf("Error writing AVRO schema to %s: %v\n", outputPath, err)
			continue
		}
		fmt.Printf("Generated %s.avsc successfully.\n", structDef.Name)
	}
}
